     "q": "แพนดายักษ์ใช้ AGS เพื่อสื่อสารเกี่ยวกับการสืบพันธุ์เพียงอย่างเดียว แต่ใช้กลิ่นปัสสาวะในการสื่อสารเกี่ยวกับการสืบพันธุ์และสื่อสารข้อมูลอื่นด้วย",
