     "answer": 0,
     "fixed": true,
     "explanation": "เพราะ เป็นความผิดปกติที่เกิดจากการมีจำนวนโครโมโซมเกินกว่าปกติเป็นจำนวนแท่ง ไม่ได้เป็นจำนวน ชุด จึงเป็นแบบ aneuploidy",
