     "fixed": true,
     "explanation": "เพราะ trisomy (การมีโครโมโซมเกินมา 1 แท่ง) สามารถพบได้ในทุกคู่ของโครโมโซม แต่ทารกมัก เสียชีวิตในครรภ์ โดย trisomy 21, trisomy 18 และ trisomy 13 เป็นความผิดปกติที่พบมาก และทารก อาจมีชีวิตรอดหลังจากคลอดแล้ว แต่จะมีอายุสั้น",
