     "concept": "พันธุศาสตร์ (Genetics)",
     "stem": "44. สามีภรรยาคู่หนึ่ง สามีเป็นโรคโลหิตจาง β-thalassemia และภรรยากำลังตั้งครรภ์ 8 สัปดาห์ แพทย์จึง\nแนะนำให้เจาะน้ำคร่ำ (AF) ตรวจดีเอ็นเอด้วยเทคนิค PCR เพื่อตรวจหายีน β-globin ของ thalassemia ที่\nมีขนาดประมาณ 520 คู่เบส และ ยีน normal β-globin ที่มีขนาดประมาณ 700 คู่เบส ขณะเดียวกันจะ\nตรวจการปนเปื้อนดีเอ็นเอของแม่จากน้ำคร่ำด้วย โดยตรวจจากตำแหน่ง D1S539 VNTR ซึ่งจะได้ชิ้นดีเอ็นเอ\nขนาด 1000-1500 คู่เบส เปรียบเทียบกับการตรวจดีเอ็นเอจากเลือดของแม่ (MB) และพ่อ (FB) จากการเพิ่ม\nปริมาณดีเอ็นเอได้ผลดังภาพ (M คือ DNA marker)",
