     "stem": "34. จากการศึกษาการอยู่ร่วมกันของจระเข้น้ำจืด 2 ชนิด คือ จระเข้สยาม (Crocodylus siamensis) กับตะโขง\n(Tomistoma schlegelii) ในพื้นที่ทะเลสาบ Mesangat ของประเทศอินโดนีเซีย ซึ่งมีสังคมพืชหลัก 2\nแบบคือ พื้นที่เปิดโล่งที่มีหญ้า (grass mat) ขึ้นหนาแน่น และพื้นที่ป่าพรุที่มีไม้ต้น (tree) ขึ้นหนาแน่น\nโดยการส ารวจด้วยวิธีพายเรือส่องไฟในเวลา 20:00-02:00 น. ในช่วงฤดูฝน ฤดูแล้ง และฤดูเปลี่ยนผ่าน\nเมื่อพบแสงสะท้อนจากดวงตา ผู้วิจัยระบุชนิด จับท าเครื่องหมาย วัดขนาดตัวเพื่อจ าแนกวัย\nและล้างท้องเพื่อศึกษาชนิดของอาหารในกระเพาะอาหาร ได้ผลดังภาพ ภาพที่ 1\nแสดงระยะทางจากจระเข้ที่พบถึงหญ้าหรือไม้ต้นที่ใกล้ที่สุด ภาพที่ 2\nแสดงจ านวนครั้งที่พบจระเข้แต่ละวัยในแต่ละฤดู ภาพที่ 3\nแสดงสัดส่วนของอาหารแต่ละประเภทที่พบในกระเพาะอาหารของจระเข้",
